mapper.select:
SELECT *
FROM com_contract
WHERE tenant_id = #{query.tenantId}
  AND master_source_system = #{query.sourceSystem}
  AND master_source_record_key = #{query.sourceRecordKey}
  AND deleted = 0
FOR UPDATE

SELECT c.* FROM com_contract c WHERE c.tenant_id = #{query.tenantId} AND c.deleted = 0 AND (
CAST(c.company_code AS BINARY) IN CAST(#{companyCode} AS BINARY)
OR
EXISTS (SELECT 1 FROM com_project_contract_relation pcr WHERE pcr.tenant_id = c.tenant_id AND pcr.contract_id = c.id AND pcr.deleted = 0 AND pcr.status = 'ACTIVE' AND pcr.effective_to IS NULL AND pcr.project_id IN #{projectId})
)
AND contract_no LIKE CONCAT('%', #{query.contractNo}, '%')
AND CAST(company_code AS BINARY) = CAST(#{query.companyCode} AS BINARY)
AND contract_type = #{query.contractType}
AND (customer_code LIKE CONCAT('%', #{query.customerKeyword}, '%') OR customer_name LIKE CONCAT('%', #{query.customerKeyword}, '%'))
AND master_source_system = #{query.sourceSystem}
AND status = #{query.status}
ORDER BY c.contract_no, c.id LIMIT #{query.offset}, #{query.limit}

SELECT COUNT(*) FROM com_contract c WHERE c.tenant_id = #{query.tenantId} AND c.deleted = 0 AND (
CAST(c.company_code AS BINARY) IN CAST(#{companyCode} AS BINARY)
OR
EXISTS (SELECT 1 FROM com_project_contract_relation pcr WHERE pcr.tenant_id = c.tenant_id AND pcr.contract_id = c.id AND pcr.deleted = 0 AND pcr.status = 'ACTIVE' AND pcr.effective_to IS NULL AND pcr.project_id IN #{projectId})
)
AND contract_no LIKE CONCAT('%', #{query.contractNo}, '%')
AND CAST(company_code AS BINARY) = CAST(#{query.companyCode} AS BINARY)
AND contract_type = #{query.contractType}
AND (customer_code LIKE CONCAT('%', #{query.customerKeyword}, '%') OR customer_name LIKE CONCAT('%', #{query.customerKeyword}, '%'))
AND master_source_system = #{query.sourceSystem}
AND status = #{query.status}

SELECT *
FROM com_contract
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.contractId}
  AND deleted = 0
FOR UPDATE
